    },
    {
      "observation_key": "claim_8",
      "content": "For PubMed node classification, GCN gets 79.1 ± 1.2 with 131.9K parameters, while QGCN gets 78.4 ± 1.4 with 41.7K parameters."
    },
    {
      "observation_key": "claim_9",
      "content": "The ROC-AUC in link prediction on CORA is 79.27 ± 0.47 for GCN with 96.0K parameters, and 83.55 ± 0.03 for QGCN with 27.2K parameters."
